def check_candidate_A():
    # Test r=3 using a small set S = {0, 1}
    S = {0, 1}

    # P1 = {f - g | f, g in S}
    P1 = set()
    for f in S:
        for g in S:
            P1.add(f - g)
    print(f"P1 for S={S}: {P1}")

    # P2 = {r * p * q | p, q in P1}. r=3.
    r = 3
    P2 = set()
    for p in P1:
        for q in P1:
            P2.add(r * p * q)
    print(f"P2 for S={S} (r=3): {P2}")

    # P3 = {x^2 + y^2 - z^2 - w^2 | x, y, z, w in P1}
    P1_sq = {x*x for x in P1}
    P3 = set()

    # Calculate P3: (x^2 + y^2) - (z^2 + w^2)
    Sums_sq = set()
    for sq1 in P1_sq:
        for sq2 in P1_sq:
            Sums_sq.add(sq1 + sq2)

    for sum_xy in Sums_sq:
        for sum_zw in Sums_sq:
            P3.add(sum_xy - sum_zw)

    print(f"P3 for S={S}: {P3}")

    # Check inclusion P2 subset of P3
    is_subset = P2.issubset(P3)
    print(f"Is P2 a subset of P3? {is_subset}")

check_candidate_A()

